            for (int j = 0; j < a[i].length; j++) {
                System.out.print(a[i][j]);

                if (j != a[i].length - 1)
                    System.out.print(", ");
            }

            System.out.print("]");

            if (i != a.length - 1)
                System.out.print(", ");
        }

        System.out.print("]");
    }
}


